import{_ as e,o as r,c as o,a6 as i}from"./chunks/framework.CCKCzdWs.js";const p=JSON.parse('{"title":"Editor settings","description":"Every setting of the Piwi extension for VS Code and of the Piwi plugin for the JetBrains IDEs, by group: connection, runs, what the editor shows, agents and advanced, with whose choice each is and where it is kept.","frontmatter":{"title":"Editor settings","description":"Every setting of the Piwi extension for VS Code and of the Piwi plugin for the JetBrains IDEs, by group: connection, runs, what the editor shows, agents and advanced, with whose choice each is and where it is kept.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/reference/editor-settings.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/reference/editor-settings.html"}],["meta",{"property":"og:title","content":"Editor settings | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Every setting of the Piwi extension for VS Code and of the Piwi plugin for the JetBrains IDEs, by group: connection, runs, what the editor shows, agents and advanced, with whose choice each is and where it is kept."}]]},"headers":[],"relativePath":"reference/editor-settings.md","filePath":"reference/editor-settings.md","lastUpdated":1795612163000}'),d={name:"reference/editor-settings.md"};function n(s,t,a,h,c,l){return r(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="editor-settings" tabindex="-1">Editor settings <a class="header-anchor" href="#editor-settings" aria-label="Permalink to &quot;Editor settings&quot;">​</a></h1><p>Both editors group their options as this page does: VS Code in its settings editor (search <code>piwi.</code>), and <strong>Settings → Tools → Piwi</strong> in a JetBrains IDE, whose help button and <strong>Documentation</strong> links open this page. A row that names one editor is that editor&#39;s alone; the JetBrains page has no Advanced group, and opens with the connection in use and a group for the desktop app.</p><p>Each option is one of three kinds:</p><ul><li><strong>The team&#39;s</strong>: one value for everyone on the project. VS Code reads it from the user or the workspace settings, which a repository may commit (<code>.vscode/settings.json</code>); a JetBrains IDE keeps it in <code>.idea/piwi.xml</code>, which the team can share.</li><li><strong>Yours, which a project may set</strong>: your choice, which a workspace&#39;s settings can set for that project. A JetBrains IDE keeps it for you in the project&#39;s <code>.idea/workspace.xml</code>.</li><li><strong>Yours</strong>: the same in every project. VS Code reads it from the user settings alone, so a repository cannot change it; a JetBrains IDE keeps it in the IDE&#39;s own settings (<code>options/piwi.xml</code>).</li></ul><p>In Rider, a project&#39;s <code>.idea</code> files sit under <code>.idea/.idea.&lt;Name&gt;/.idea/</code>, as the settings page says.</p><h2 id="connection" tabindex="-1">Connection <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;Connection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it chooses</th><th>Default</th><th>Kind</th></tr></thead><tbody><tr><td><code>piwi.serverUrl</code></td><td>The Piwi instance. <code>PIWI_DASHBOARD_URL</code> in the environment or the workspace <code>.env</code> comes first, then this, then the desktop app while it runs: <a href="/features/editor-connection.html">Editor connection</a></td><td>none</td><td>The team&#39;s</td></tr><tr><td><code>piwi.project</code></td><td>The project&#39;s name or id on the instance</td><td>none</td><td>The team&#39;s</td></tr><tr><td>JetBrains: <strong>Read this project from the desktop app while it runs</strong></td><td>Whether the desktop app comes first while it runs; VS Code chooses it with <strong>Piwi: Connect…</strong></td><td>off</td><td>Yours, which a project may set</td></tr><tr><td>JetBrains: <strong>Desktop app project</strong></td><td>The project&#39;s name in the desktop app; empty uses the one linked there to this folder</td><td>none</td><td>Yours, which a project may set</td></tr></tbody></table><p>The API key is kept in the editor&#39;s secret storage (VS Code) or the IDE&#39;s password safe, for its instance alone, and the choice of the desktop app on this machine only.</p><h2 id="runs" tabindex="-1">Runs <a class="header-anchor" href="#runs" aria-label="Permalink to &quot;Runs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it chooses</th><th>Default</th><th>Kind</th></tr></thead><tbody><tr><td><code>piwi.runNotifications</code></td><td>When a run ends, whether a notification says what it changed: always, only when something fails, or never</td><td>Say what it changed when something fails</td><td>Yours</td></tr><tr><td><code>piwi.runNotificationsScope</code></td><td>The runs it says it for: the runs started here, or also the branch&#39;s CI runs</td><td>The runs started here and the branch&#39;s CI runs</td><td>Yours</td></tr><tr><td><code>piwi.statusBarAlert</code></td><td>When the status bar item turns red: for a new failure a run started here caused, for any failing test, or never</td><td>For a new failure a run started here caused</td><td>Yours</td></tr><tr><td><code>piwi.breakpoints</code></td><td>Which runs pause at the editor&#39;s breakpoints, Debug with Piwi, every run or none: <a href="/features/editor-breakpoints.html">Editor breakpoints</a></td><td>Debug with Piwi</td><td>Yours</td></tr><tr><td><code>piwi.runHeaded</code></td><td>Whether every run Piwi starts runs headed, its browser window shown</td><td>off</td><td>Yours</td></tr><tr><td><code>piwi.runHoldFailures</code></td><td><a href="/features/watch-a-run.html">Hold failures</a> from each run&#39;s start: Auto, On or Off</td><td>Auto</td><td>Yours</td></tr><tr><td><code>piwi.testExplorer</code></td><td>VS Code: whether the Testing view lists Piwi&#39;s tests, with their results; off leaves the view to another extension&#39;s tree, such as Microsoft&#39;s Playwright Test</td><td>on</td><td>Yours, which a project may set</td></tr><tr><td>JetBrains: <strong>Run the tests in the IDE&#39;s Playwright runner</strong></td><td>Whether a run starts in the IDE&#39;s Playwright runner (a test tree, Debug, Rerun Failed Tests) or in the Run tool window&#39;s console. The runner comes with the IDE&#39;s JavaScript plugin, as in WebStorm, IntelliJ IDEA Ultimate and Rider; where it lacks one, the option is off and says why</td><td>off</td><td>Yours</td></tr></tbody></table><h2 id="in-the-editor" tabindex="-1">In the editor <a class="header-anchor" href="#in-the-editor" aria-label="Permalink to &quot;In the editor&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it chooses</th><th>Default</th><th>Kind</th></tr></thead><tbody><tr><td><code>piwi.codeLens</code></td><td>The lines Piwi writes above the code: every line, a failure&#39;s and an uncovered change&#39;s alone, or none. A test&#39;s gutter mark stays</td><td>Every line</td><td>Yours</td></tr><tr><td><code>piwi.gutterIcons</code></td><td>VS Code: each test&#39;s latest result in the gutter; off, its line keeps the hover. A JetBrains IDE switches it under <strong>Settings → Editor → General → Gutter Icons → Piwi test results</strong></td><td>on</td><td>Yours</td></tr><tr><td><code>piwi.coverageMarks</code></td><td>The coverage marks at the left of the lines: <a href="/features/editor-coverage.html">Editor coverage</a></td><td>on</td><td>Yours</td></tr><tr><td><code>piwi.failureSeverity</code></td><td>How a failure shows at its line: an error, a warning, information (a weak warning in a JetBrains IDE), or nothing in the problems</td><td>An error</td><td>Yours, which a project may set</td></tr><tr><td><code>piwi.locatorWarnings</code></td><td>Whether a locator the <a href="/reference/locator-stability.html">locator stability rules</a> find brittle is warned at, with its stable alternative as a quick fix</td><td>on</td><td>Yours</td></tr><tr><td><code>piwi.failingTestTint</code></td><td>Whether a failing test and the line it failed at are tinted; the gutter still marks them, unless <code>piwi.gutterIcons</code> is off</td><td>on</td><td>Yours</td></tr><tr><td><code>piwi.ciPositions</code></td><td>Whether a CI run of the branch shows where it stands, at the end of each line: <a href="/features/editor-ci-runs.html">Editor CI runs</a></td><td>on</td><td>Yours</td></tr><tr><td><code>piwi.runningLines</code></td><td>Which lines of your run are marked as running: every running test&#39;s, the watched worker&#39;s alone, or none: <a href="/features/watch-running-test.html#the-running-line">The running line</a></td><td>Every running test&#39;s</td><td>Yours</td></tr></tbody></table><h2 id="agents-mcp" tabindex="-1">Agents (MCP) <a class="header-anchor" href="#agents-mcp" aria-label="Permalink to &quot;Agents (MCP)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it chooses</th><th>Default</th><th>Kind</th></tr></thead><tbody><tr><td><code>piwi.mcpAuthorization</code></td><td>How the agent signs in to Piwi&#39;s MCP server: with the editor&#39;s API key, or a sign-in in the browser</td><td>The editor&#39;s API key</td><td>Yours</td></tr><tr><td><code>piwi.serveRunsToAgents</code></td><td>Whether the test runs started here are served to the agents of this machine, as an MCP server on <code>127.0.0.1</code></td><td>on</td><td>Yours, which a project may set</td></tr></tbody></table><h2 id="advanced" tabindex="-1">Advanced <a class="header-anchor" href="#advanced" aria-label="Permalink to &quot;Advanced&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it chooses</th><th>Default</th><th>Kind</th></tr></thead><tbody><tr><td><code>piwi.hiddenMessages</code></td><td>VS Code: the kinds of messages <strong>Don&#39;t Show Again</strong> hid: <code>agent-let-go</code> (a stop an agent held goes on once the agent went idle), <code>window-shared</code> (a run is shared live, as the window&#39;s runs are), <code>unattended-resumed</code> (a test stopped where nobody attends the run goes on), <code>reporter-missing</code> (a run did not reach the instance, from a config without the Piwi reporter) and <code>picker-inserted</code> (what Piwi Picker inserted at the cursor). Remove a kind to see its message again</td><td>none</td><td>Yours</td></tr><tr><td><code>piwi.trace.server</code></td><td>VS Code: whether the traffic with the editor service is traced in the Piwi output channel</td><td>Off</td><td>Yours</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/editors.html">Editor extensions</a>: what the extensions show, and how they connect.</li><li><a href="/features/jetbrains.html">JetBrains plugin</a>: what the plugin needs and draws differently.</li><li><a href="/reference/editor-commands.html">Editor commands</a>: every command of both editors.</li></ul>',18)])])}const w=e(d,[["render",n]]);export{p as __pageData,w as default};
